"""
DynamicMeshTopologyOptimizer

Modulo per l'ottimizzazione euristica della matrice di adiacenza del cluster
P2P, basata su latenza e larghezza di banda. La classe è thread-safe e fornisce
metodi concreti per il calcolo dei pesi, la ristrutturazione topologica e la
valutazione delle metriche di rete.
"""

import threading
from typing import List, Tuple, Dict, Optional
import random
import heapq


class DynamicMeshTopologyOptimizer:
    """
    Ottimizzatore euristico della topologia mesh P2P.

    Gestisce una matrice di adiacenza dinamica e la ottimizza per minimizzare
    latenza e massimizzare banda. Thread-safe tramite un lock interno.
    """

    def __init__(self, num_nodes: int, latency_matrix: List[List[float]],
                 bandwidth_matrix: List[List[float]]) -> None:
        """
        Inizializza l'ottimizzatore con i parametri del cluster.

        Args:
            num_nodes: Numero di nodi nel cluster.
            latency_matrix: Matrice di latenza (row = sorgente, col = destinazione).
            bandwidth_matrix: Matrice di banda (row = sorgente, col = destinazione).
        """
        self._num_nodes = num_nodes
        self._latency = [row[:] for row in latency_matrix]
        self._bandwidth = [row[:] for row in bandwidth_matrix]
        self._adjacency = self._compute_initial_adjacency()
        self._lock = threading.RLock()

    def _compute_initial_adjacency(self) -> List[List[float]]:
        """
        Calcola la matrice di adiacenza iniziale combinando latenza e banda.

        Il peso di un arco è definito come:
            weight = (1 / latency) * bandwidth
        Arco esistente se la latenza è inferiore a una soglia.
        """
        n = self._num_nodes
        adj = [[0.0] * n for _ in range(n)]
        for i in range(n):
            for j in range(n):
                if i != j and self._latency[i][j] < 10.0:  # soglia arbitraria
                    weight = (1.0 / self._latency[i][j]) * self._bandwidth[i][j]
                    adj[i][j] = weight
        return adj

    @property
    def adjacency(self) -> List[List[float]]:
        """Restituisce la matrice di adiacenza corrente."""
        with self._lock:
            return [row[:] for row in self._adjacency]

    @property
    def num_nodes(self) -> int:
        """Numero di nodi nel cluster."""
        return self._num_nodes

    def compute_edge_weights(self, i: int, j: int) -> float:
        """
        Calcola il peso dell'arco (i, j) basato su latenza e banda.

        Args:
            i: Indice del nodo sorgente.
            j: Indice del nodo destinazione.

        Returns:
            Peso dell'arco.
        """
        with self._lock:
            if i == j:
                return 0.0
            latency = self._latency[i][j]
            bandwidth = self._bandwidth[i][j]
            if latency <= 0.0:
                return 0.0
            return (1.0 / latency) * bandwidth

    def find_nearest_neighbors(self, node: int, k: int = 3) -> List[int]:
        """
        Trova i k vicini più vicini per un nodo dato in base al peso di adiacenza.

        Args:
            node: Indice del nodo.
            k: Numero di vicini da restituire.

        Returns:
            Lista di indici dei vicini ordinati per peso decrescente.
        """
        with self._lock:
            weights = [(self._adjacency[node][j], j) for j in range(self._num_nodes)
                       if j != node and self._adjacency[node][j] > 0.0]
            weights.sort(reverse=True)
            return [neighbor for _, neighbor in weights[:k]]

    def optimize_topology(self, iterations: int = 10, decay_factor: float = 0.5) -> None:
        """
        Ottimizza la topologia combinando latenza e banda in modo euristico.

        L'algoritmo iterativo riduce i pesi degli archi con alta latenza e
        aumenta quelli con alta banda, fino a convergenza o numero di iterazioni.

        Args:
            iterations: Numero massimo di passate di ottimizzazione.
            decay_factor: Fattore di decadimento per i pesi non ottimali.
        """
        with self._lock:
            for _ in range(iterations):
                # Calcola i pesi attuali
                current_weights = [self._adjacency[i][j] for i in range(self._num_nodes)
                                   for j in range(self._num_nodes) if i != j]
                # Identifica archi da migliorare (bassa banda, alta latenza)
                improvements = []
                for i in range(self._num_nodes):
                    for j in range(self._num_nodes):
                        if i == j:
                            continue
                        current = self._adjacency[i][j]
                        latency = self._latency[i][j]
                        bandwidth = self._bandwidth[i][j]
                        # Calcola punteggio di qualità: preferisci alta banda, bassa latenza
                        quality = (bandwidth / (latency + 1e-6)) * current
                        improvements.append((quality, i, j))

                # Ordina per qualità decrescente e applica aggiornamenti
                improvements.sort(reverse=True)
                for _, i, j in improvements:
                    if self._adjacency[i][j] > 0.0:
                        # Riduci il peso se la qualità è bassa
                        current = self._adjacency[i][j]
                        latency = self._latency[i][j]
                        bandwidth = self._bandwidth[i][j]
                        new_weight = current * decay_factor
                        # Se la latenza è alta e la banda è bassa, riduci ulteriormente
                        if latency > 5.0 and bandwidth < 1.0:
                            new_weight *= 0.8
                        self._adjacency[i][j] = new_weight

    def compute_metrics(self) -> Dict[str, float]:
        """
        Calcola metriche di rete: latenza media, banda media, densità.

        Returns:
            Dizionario con chiavi 'avg_latency', 'avg_bandwidth', 'density'.
        """
        with self._lock:
            total_latency = 0.0
            total_bandwidth = 0.0
            count = 0
            for i in range(self._num_nodes):
                for j in range(self._num_nodes):
                    if i != j and self._adjacency[i][j] > 0.0:
                        total_latency += self._latency[i][j]
                        total_bandwidth += self._bandwidth[i][j]
                        count += 1
            avg_latency = total_latency / count if count else 0.0
            avg_bandwidth = total_bandwidth / count if count else 0.0
            density = count / (self._num_nodes * (self._num_nodes - 1)) if self._num_nodes > 1 else 0.0
            return {
                "avg_latency": avg_latency,
                "avg_bandwidth": avg_bandwidth,
                "density": density
            }

    def update_parameters(self, latency_matrix: List[List[float]],
                         bandwidth_matrix: List[List[float]]) -> None:
        """
        Aggiorna le matrici di latenza e banda e ricalcola l'adiacenza.

        Args:
            latency_matrix: Nuova matrice di latenza.
            bandwidth_matrix: Nuova matrice di banda.
        """
        with self._lock:
            self._latency = [row[:] for row in latency_matrix]
            self._bandwidth = [row[:] for row in bandwidth_matrix]
            self._adjacency = self._compute_initial_adjacency()